meta.script:

var headline_count;
var headline_interval;
var old_headline = 0;
var current_headline=0;

$(document).ready(function(){
  headline_count = $("div.headline").size();
  $("div.headline:eq("+current_headline+")").css('top','5px');

  headline_interval = setInterval(headline_rotate,5000); //time in milliseconds
  $('#scrollup').hover(function() {
    clearInterval(headline_interval);
  }, function() {
  headline_interval = setInterval(headline_rotate,5000); //time in milliseconds
  headline_rotate();        
  });
});


function headline_rotate() {
  current_headline = (old_headline + 1) % headline_count; //remainder will always equal old_headline until it reaches headline_count - at which point it becomes zero. clock arithmetic
  $("div.headline:eq(" + old_headline + ")").animate({top: -205},"slow", function() {
    $(this).css('top','210px');
    });
  $("div.headline:eq(" + current_headline + ")").show().animate({top: 5},"slow");  
  old_headline = current_headline;
}

div.script:
		$(document).ready(
      function(){

		setTimeout(initScroller, 1000);

      }
      );

		function initScroller(){
       initCompanyInfo();
        scrollArrowWidth = $('.scrollArrow').width();
		paneWidth = $('#pane').css('width');
        paneWidth = paneWidth.substring(0,paneWidth.length-2);
		//alert(paneWidth - (scrollArrowWidth*2)+'px');
		//$('#sliderTrack').css('width', paneWidth - (scrollArrowWidth*2)+'px');

        cordx = 0;
        areaWidth = $("#slidearea").css("width");
        areaWidth = areaWidth.substring(0,areaWidth.length-2);

        maxX = paneWidth - areaWidth;

             $('#sliderTrack').Slider(
          {
          accept : '#slider',
          fractions : 100,
          onSlide : function( cordx, cordy, x , y)
            {
            /*
                curLeft = $("#slidearea").css("left");
                curLeft = curLeft.substring(0, (curLeft.length-2));
                */
              //alert((maxX * (cordx/100))+"px");
              $("#slidearea").css("left", (maxX * (cordx/100))+"px");

              cordx = (1024/100)*cordx;
            },
            values: [
              [0,0]
            ]
          }
        );  
        $('#go-right').click(function(){
          $('#sliderTrack').SliderSetValues(
            [
            [100,100]
            ]
          );
        });
        $('#go-left').click(function(){
          $('#sliderTrack').SliderSetValues(
            [
            [-100,-100]
            ]
          );
        });
		}

      function initSlider(){
           $('#sliderTrack').Slider(
          {
          accept : '#slider',
          fractions : 50,
          onSlide : function( cordx, cordy, x , y)
            {

              $("#slidearea").css("left", (maxX * (cordx/100))+"px");

              cordx = (1024/100)*cordx;
            },
            values: [
              [0,0]
            ]
          }
        );
      }
      function initCompanyInfo(){
           $('.companyLogo').click(function()
          {

            $('#secondarycolumn').find("div").html('');

            var name = $(this).attr("title");
            name = name.substring(0, (name.length));
//alert("/direct/OurPortfolio/?_query=for%20$portfolio%20in%20//entry[@name='" + name + "']%20return%20$portfolio");
            $.ajax({
              type: "GET",
              url: "/direct/OurPortfolio/",
              data: "_query=for%20$portfolio%20in%20//entry[@name='" + name + "']%20return%20$portfolio//content",
              success: function(xmlData){
              var content = $(xmlData);
                $('#portfolio-company-overview').html($(content).text());
              }
            });
          }
        );
      }
